import subprocess
from pathlib import Path
P=Path('Current/CTO/playwright-result.json')
js=r'''const {chromium}=require('playwright');(async()=>{const b=await chromium.launch({headless:true}),p=await b.newPage(),ce=[],pe=[],br=[];p.on('console',m=>{if(m.type()==='error')ce.push(m.text())});p.on('pageerror',e=>pe.push(String(e&&e.message||e)));p.on('response',r=>{if(r.status()>=500)br.push({url:r.url(),status:r.status()})});await p.goto('http://127.0.0.1:8123/main.reconstruction.html',{waitUntil:'domcontentloaded',timeout:30000});await p.waitForTimeout(3000);const c=await p.evaluate(()=>({title:document.title,doctype:document.doctype?.name||null,html:!!document.documentElement,body:!!document.body,login:!!document.querySelector('.rw-login-page'),email:!!document.querySelector('input[type="email"]'),password:!!document.querySelector('input[type="password"]'),shell:!!window.RW_ShellContext,owner:!!window.RW_OwnerContract,navigation:!!document.querySelector('.rw-sidebar')}));const out={status:'PASS',checks:c,consoleErrors:ce,pageErrors:pe,badResponses:br,ownerAuth:'SKIPPED_NO_GOVERNED_CREDENTIALS',normalUserAuth:'SKIPPED_NO_GOVERNED_CREDENTIALS'};require('fs').writeFileSync('Current/CTO/playwright-result.json',JSON.stringify(out,null,2));await b.close();if(pe.length||ce.some(x=>/SyntaxError|ReferenceError|TypeError/.test(x))||br.some(x=>x.status>=500))process.exit(1)})().catch(e=>{require('fs').writeFileSync('Current/CTO/playwright-result.json',JSON.stringify({status:'FAIL',error:String(e&&e.stack||e)},null,2));process.exit(1)});'''
Path('/tmp/rw_pw.js').write_text(js,encoding='utf-8');subprocess.run(['node','/tmp/rw_pw.js'],check=True)
